    fflush(stdout);
    /* Close write end of pipe to signal EOF */
    close(capture->pipe_write_fd);
    /* Restore original stdout */
    dup2(capture->saved_stdout_fd, STDOUT_FILENO);
    close(capture->saved_stdout_fd);
    /* Read captured output from pipe */
    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(capture->pipe_read_fd);
        free(capture);
        return NULL;
